            int functionRva, int rva, int length, int footerRva, string originalHex,
            string signatureHex, string continuationHex, string footerHex)
        { Name=name; Kind=kind; FunctionRva=functionRva; Rva=rva; Length=length; FooterRva=footerRva;
          OriginalHex=originalHex; SignatureHex=signatureHex; ContinuationHex=continuationHex; FooterHex=footerHex; }
        internal string Name { get; }
        internal WorkerProductionBonusNativeKind Kind { get; }
        internal int FunctionRva { get; }
        internal int Rva { get; }
        internal int Length { get; }
        internal int FooterRva { get; }
        internal string OriginalHex { get; }
        internal string SignatureHex { get; }
        internal string ContinuationHex { get; }
        internal string FooterHex { get; }
        internal byte[] OriginalBytes => WorkerProductionBonusNativeDefinition.Hex(OriginalHex);
    }

